#!/usr/bin/env bash
# Self-test for tests/gate_lib.sh: pins the step-line contract the two gates and
# the Python docs check read — `gate_run` prints `PASS  <name>`, and when the
# call carries `INV-NN` words from docs/agents/invariants.md right after the
# timeout, each is printed inside the PASS line as `PASS  [INV-NN] <name>`
# (`INV-06`). The id is omitted cleanly when absent, the SKIP/FAIL wording is
# unchanged by the id, and the status reaches the caller either way.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.

set -u

. "${BASH_SOURCE[0]%/*}/gate_lib.sh"

gate_top
GATE="$ROOT/tests/gate_lib.sh"
[ -f "$GATE" ] || { echo "self-test: gate library not found at $GATE" >&2; exit 2; }

gate_sandbox pime-gate-lib-selftest || { echo "self-test: no sandbox" >&2; exit 2; }
export BUILD_DIR="$tmp"

failures=0
expect() { # want-line got-line label
    if [ "$1" = "$2" ]; then
        printf 'ok    %s\n' "$3"
    else
        printf 'FAIL  %s: want %s, got %s\n' "$3" "$1" "$2"
        failures=$((failures + 1))
    fi
}

# 1. No id: the bare PASS line, two spaces after the word, nothing invented.
out=$(gate_run 'no-id step' 5 true)
expect 'PASS  no-id step' "$out" 'PASS omits the id cleanly when absent'

# 2. One id: printed in its own brackets before the name. The id words sit
#    right after the timeout — the position step() hands them over in.
out=$(gate_run 'declared step' 5 INV-06 true)
expect 'PASS  [INV-06] declared step' "$out" 'PASS prints the declared id'

# 3. Several ids: one bracket each, in call order, name last.
out=$(gate_run 'suite step' 5 INV-02 INV-04 INV-05 true)
expect 'PASS  [INV-02] [INV-04] [INV-05] suite step' "$out" \
    'PASS prints every declared id in order'

# 4. A non-id first word ends the id run; the command still runs and the FAIL
#    wording is untouched by the id.
out=$(gate_run 'failing step' 5 INV-06 false)
expect 'FAIL  failing step (exit 1)' "$out" 'FAIL keeps its wording with an id'
gate_run 'status step' 5 INV-06 false >/dev/null
status=$?
expect '1' "$status" 'the exit status reaches the caller with an id'

# 5. The not-applicable 125 keeps its SKIP wording; like the PASS, it satisfies
#    the step, so the library returns 0 after printing it (the counters live in
#    the caller's skip()/step() mapping).
out=$(gate_run 'skip step' 5 INV-03 bash -c 'exit 125')
expect 'SKIP  skip step (not applicable here)' "$out" 'SKIP wording unchanged'
gate_run 'skip status' 5 INV-03 bash -c 'exit 125' >/dev/null
expect '0' "$?" 'the 125 answer satisfies the step like a pass'

# 6. The watchdog path: a step outliving its bound is taken down with its
#    session and reported HANG (only where setsid exists to own the session).
if command -v setsid >/dev/null 2>&1; then
    out=$(gate_run 'hung step' 1 INV-06 sleep 5)
    expect 'HANG  hung step (killed after 1s; rerun by hand: sleep 5)' "$out" \
        'HANG names the bound and the command'
fi

if [ "$failures" -ne 0 ]; then
    printf 'gate-library self-test: %d case(s) failed\n' "$failures" >&2
    exit 1
fi
printf 'gate-library self-test passed\n'
